from pathlib import Path
p=Path('app.html'); s=p.read_text(); s=s.replace('<p id="position-list-status">Loading eligible positions…</p>','').replace('<button id="position-row" class="position-row hidden" type="button" aria-selected="false"><strong id="position-row-name"></strong><span id="position-row-meta"></span><b id="position-row-amount"></b></button>',''); p.write_text(s)
p=Path('app.js'); s=p.read_text(); s=s.replace('setText("#position-list-status",positions.length?`${positions.length} position${positions.length===1?"":"s"} detected`:"No positions detected"); ',''); s=s.replace('setText("#position-list-status","Portfolio unavailable — no positions loaded");',''); s=s.replace('setText("#position-list-status",view.positionLabel);',''); s=s.replace('setText("#position-list-status","Wallet-bound positions unavailable during network switch.");',''); start='const name=p.name||p.protocol||"Kamino position",asset=p.asset||"USDG",assessment=authorityAssessment(data);if(listStatus)listStatus.textContent="1 position detected";if(row){row.classList.remove("hidden");row.setAttribute("aria-selected","false");setText("#position-row-name",name);setText("#position-row-meta",`${p.protocol||"Kamino"} · ${CURRENT_NETWORK==="devnet"?"Devnet":"Mainnet"} · ${asset}`);setText("#position-row-amount",`${format(p.underlyingAmount)} ${asset}`);row.onclick=()=>{row.setAttribute("aria-selected","true");detail?.classList.remove("hidden");tabs?.classList.remove("hidden");document.querySelectorAll("[id^=position-subpane-]").forEach(x=>x.classList.toggle("hidden",x.id!=="position-subpane-overview"))}}'
repl='const name=p.name||p.protocol||"Kamino position",asset=p.asset||"USDG",assessment=authorityAssessment(data);'
if start not in s: raise SystemExit('renderer block not found')
s=s.replace(start,repl).replace(',row=$("#position-row"),detail=$("#position-card"),empty=$("#no-position"),listStatus=$("#position-list-status")',',detail=$("#position-card"),empty=$("#no-position")')
p.write_text(s)
p=Path('styles.css'); s=p.read_text(); import re; s=re.sub(r'#position-list\{margin-top:34px.*?\}\n?', '', s); p.write_text(s)
